`timescale 1 ns/1 ps
module topDecoder(clk, reset, sIn, uO, bO, pO4);

   input wire clk;
   input wire reset;
   input wire [4:0] sIn;

   output reg [125:0] uO;
   output reg [19:0] bO;
   output reg [7:0] pO4;

   wire 	     clk_out;
   reg [7:0] 	     pO0;
   reg [7:0] 	     pO1;
   reg [7:0] 	     pO2;
   reg [7:0] 	     pO3;
   
   SIPO_5to40b(clk, reset, sIn, pO0, pO1, pO2, pO3, pO4);
        
   divideByEight(clk, clk_out);

   b2u_16bits(clk_out, {pO0[7:0], pO1[1:0]}, {pO2[7:0], pO3[1:0]}, pO1[7:2], pO3[7:2], uO, bO);

endmodule // top

module SIPO_5to40b (clk, reset, sIn, pOut0, pOut1, pOut2, pOut3, pOut4);

	input clk;
	input reset;
	input [4:0] sIn;
	output reg [7:0] pOut0;
	output reg [7:0] pOut1;
	output reg [7:0] pOut2;
	output reg [7:0] pOut3;
	output reg [7:0] pOut4;

	always @ ( posedge clk or negedge reset)
	begin
		if (!reset)
			begin
				pOut0 <= 8'b0;
				pOut1 <= 8'b0;
				pOut2 <= 8'b0;
				pOut3 <= 8'b0;
				pOut4 <= 8'b0;
			end
		else
			begin
				pOut0[7:0] <= {pOut0[6:0],sIn[0]};
				pOut1[7:0] <= {pOut1[6:0],sIn[1]};
				pOut2[7:0] <= {pOut2[6:0],sIn[2]};
				pOut3[7:0] <= {pOut3[6:0],sIn[3]};
				pOut4[7:0] <= {pOut4[6:0],sIn[4]};
			end
	end
endmodule

module divideByEight(input clk, output clk_out);
   
   //output clk_out;
   //wire clk_out;

   //input clk;
   //wire  clk;

   reg [2:0] m;

   initial m = 0;
   always@(posedge(clk)) begin
      m<=m+1;
   end

   assign clk_out = m[2];

endmodule // divideByEight
     
